/* Zekulhyda storefront behaviour.
   Ported from the reference design (zekulhyda-site_8.html) so the storefront behaves like
   the approved prototype: hero slideshow, medal badges, partner marquee, flavour strip,
   scroll reveals and the tasting-package estimator.

   Deliberately NOT ported: the prototype's own cart, product grid and filters. Shopify
   owns the catalogue and the cart, so those render targets do not exist in the theme and
   the inert-node shim below turns their code paths into no-ops. */

function ZKI(name) { return (window.ZK_IMG || {})[name] || ''; }

var ZK_INERT = new Proxy(function () {}, {
  get: function (t, k) {
    if (k === 'length') return 0;
    if (k === 'value' || k === 'innerHTML' || k === 'textContent') return '';
    if (k === Symbol.iterator) return function* () {};
    if (k === 'hidden') return true;
    return ZK_INERT;
  },
  set: function () { return true; },
  apply: function () { return ZK_INERT; },
  has: function () { return true; }
});


