const FLAVORS = [["ds-lamaie","#F2E24A"],["ds-portocale","#F2A23A"],["ds-mandarina","#F0B84A"],["ds-grepfrut","#E85C8A"],["ds-lime","#8BD24A"],["ds-banane","#F5D93A"],["ds-ghimbir","#E5405A"]];
