const MEDALS=[["md1","gold"],["md2","champ"],["md3","gold"],["md4","silver"],["md5","gold"],["md6","gold"]];
const METAL={gold:["#F6E3A1","#C9963B","#7A5416"],champ:["#FFF1C2","#E4B65A","#8A5F1E"],silver:["#F2F2F2","#B9BCC2","#6E7178"]};
function medalSVG(key,kind,i){
  const [a,b,c]=METAL[kind]; const id='m'+i;
  return `<svg viewBox="0 0 200 200" role="img" aria-label="${t(key+'_ring')}"><defs><linearGradient id="${id}a" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".5" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></linearGradient><linearGradient id="${id}b" x1="1" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${a}"/><stop offset=".55" stop-color="${b}"/><stop offset="1" stop-color="${c}"/></linearGradient><path id="${id}p" d="M100,100 m-72,0 a72,72 0 1,1 144,0 a72,72 0 1,1 -144,0"/></defs>
<circle cx="100" cy="100" r="98" fill="url(#${id}a)"/><circle cx="100" cy="100" r="92" fill="none" stroke="${c}" stroke-opacity=".5" stroke-width="1"/><circle cx="100" cy="100" r="88" fill="url(#${id}b)"/><circle cx="100" cy="100" r="58" fill="#0F0F11"/><circle cx="100" cy="100" r="55" fill="none" stroke="${a}" stroke-opacity=".6" stroke-width=".8"/>
<text font-family="IBM Plex Mono,monospace" font-size="9.5" letter-spacing="2.2" fill="#1a1408" font-weight="500"><textPath href="#${id}p" startOffset="50%" text-anchor="middle">${t(key+'_ring')}</textPath></text>
<text x="100" y="${key==='md4'?'112':'108'}" text-anchor="middle" font-family="Cormorant Garamond,serif" font-size="${key==='md5'?'34':'40'}" fill="${a}">${t(key+'_c')}</text>
<text x="100" y="130" text-anchor="middle" font-family="IBM Plex Mono,monospace" font-size="7.5" letter-spacing="1.6" fill="${b}">${t(key+'_l').toUpperCase()}</text>
<path d="M40 40 q60 -40 120 0" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="6" stroke-linecap="round"/></svg>`;
}
function renderMedals(){
  $('#medals').innerHTML = MEDALS.map(([k,kind],i)=>`<a class="badge-m" href="/collections/premiate" data-f="premiate">${medalSVG(k,kind,i)}<span class="l">${t(k+'_ring').split(' · ')[0]}</span></a>`).join('') + `<p class="medals-note">${t('medals_note')}</p>`;
}
function selectPack(i){
  document.querySelectorAll('.pack').forEach(p=>p.classList.toggle('sel',p.dataset.pack==String(i)));
  const sel=$('#bkPack'); if(sel) sel.selectedIndex=i;
  if(typeof estimate==='function') estimate();
}
